//! Vectors for the verifier's side of FOLDEQ, generated by
//! `scripts/cpp_vectors/foldeq_vectors.cpp`. Every expected value comes from the fixture.

use std::collections::HashMap;

use fp_core::chain::public::PublicBytes;
use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::foldeq::{
    block_sums, digest_bytes, foldeq_column_row, foldeq_fault, foldeq_record_row, foldeq_symbol,
    foldeq_weights, index_fault, index_key_fault, index_name, index_tree, priced_table,
    record_bytes, record_fault, record_seeds, record_value, vector_lay, vector_room, BlockSums,
    FoldedRow, FoldeqShape, IndexKey, IndexName, IndexReader, IndexRecord, IndexShape,
    TableStanding, VectorLay, E_DEGREE,
};
use fp_core::iop::message::Writer;
use fp_core::iop::relation::{Codes, OracleShape, Part, Row, RowKind, Statement};
use fp_core::iop::tensor::Tensor;
use fp_core::numbers::plan::{TableDistances, TableTest};

const VECTORS: &str = include_str!("../../fixtures/foldeq_vectors.txt");

fn vector_fields() -> HashMap<&'static str, &'static str> {
    VECTORS
        .split_whitespace()
        .filter_map(|t| t.split_once('='))
        .collect()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn eseq(s: &str) -> Vec<E> {
    if s == "-" {
        Vec::new()
    } else {
        s.split(';').map(e).collect()
    }
}

fn ulist(s: &str) -> Vec<u64> {
    if s == "-" {
        Vec::new()
    } else {
        s.split(',').map(|x| x.parse().unwrap()).collect()
    }
}

fn hex_bytes(s: &str) -> Vec<u8> {
    if s == "-" {
        return Vec::new();
    }
    assert!(s.len() % 2 == 0, "hex {}", s);
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

/// A digest printed as its bytes (`digest_bytes`).
fn digest(s: &str) -> Digest {
    let b = hex_bytes(s);
    let mut out = [0u8; 32];
    out.copy_from_slice(&b);
    Digest::from_bytes(&out)
}

/// A digest printed word by word (`pd` in the C++ tool, and `put_digest` in the name).
fn digest_words(s: &str) -> Digest {
    let mut d = Digest::zero();
    for (i, w) in d.w.iter_mut().enumerate() {
        *w = u32::from_str_radix(&s[8 * i..8 * i + 8], 16).unwrap();
    }
    d
}

fn public_bytes<T: PublicBytes>(x: &T) -> Vec<u8> {
    let mut w = Writer::default();
    x.public_bytes(&mut w);
    w.bytes().to_vec()
}

fn fault_text(f: Option<&'static str>) -> String {
    match f {
        None => "-".to_string(),
        Some(m) => m.replace(' ', "_"),
    }
}

fn kind(s: &str) -> RowKind {
    match s {
        "0" => RowKind::Plain,
        "1" => RowKind::Sample,
        "2" => RowKind::Generator,
        _ => panic!("kind {}", s),
    }
}

fn sane(s: &str) -> String {
    s.replace(' ', "_")
}

fn check_row(kv: &HashMap<&str, &str>, p: &str, oracle: u32, row: &Row, bits: u32) {
    assert_eq!(row.kind, kind(kv[&format!("{}_KIND", p)[..]]), "{} kind", p);
    assert_eq!(sane(&row.name), kv[&format!("{}_NAME", p)[..]], "{} name", p);
    assert_eq!(row.target, e(kv[&format!("{}_TARGET", p)[..]]), "{} target", p);
    let want = eseq(kv[&format!("{}_COEF", p)[..]]);
    assert_eq!(want.len(), 1usize << bits, "{} coefficients", p);
    for (j, v) in want.iter().enumerate() {
        assert_eq!(row.coefficient(oracle, Part::Main, j as u64), *v, "{} coefficient {}", p, j);
    }
}

fn lay_shape(tag: &str) -> (OracleShape, bool, u32) {
    match tag {
        "LAY_A" => (shape(4, 3, 1), false, 1),
        "LAY_B" => (shape(3, 3, 1), false, 1),
        "LAY_C" => (shape(3, 3, 1), true, 1),
        "LAY_D" => (shape(4, 3, 2), true, 2),
        _ => panic!("tag {}", tag),
    }
}

fn shape(rows: usize, deg: u32, answers: u32) -> OracleShape {
    OracleShape {
        name: "lay".into(),
        code: 0,
        main_rows: rows,
        main_deg: deg,
        mask_rows: 0,
        mask_code: 0,
        answers,
    }
}

fn index_shape() -> IndexShape {
    IndexShape {
        code: Code { log_n: 4, ell: 8, r: 4 },
        v: 2,
        answers: 2,
        salt_bytes: 40,
        distances: TableDistances { radius: 3, later_radius: 4, m_once: 5, m_later: 6 },
    }
}

fn fold_shape() -> FoldeqShape {
    FoldeqShape {
        index: index_shape(),
        u: OracleShape { name: "folded row".into(), ..shape(4, 3, 1) },
        rows_high: false,
        leaf_class: 7,
        columns: 5,
    }
}

fn codes() -> Codes {
    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 4, ell: 8, r: 4 });
    codes.mask.push(Code { log_n: 3, ell: 4, r: 2 });
    codes
}

#[test]
fn foldeq_vectors_match_the_cpp_reference() {
    let kv = vector_fields();

    // Placement: index, inverse, room and a structured vector on the table.
    let z = vec![E([F(11), F(12), F(13)]), E([F(12), F(13), F(14)]), E([F(13), F(14), F(15)])];
    for tag in ["LAY_A", "LAY_B", "LAY_C", "LAY_D"] {
        let (s, rows_high, _) = lay_shape(tag);
        let lay: VectorLay = vector_lay(&codes(), &s, rows_high);
        assert_eq!(lay.row_bits, kv[&format!("{}_ROW_BITS", tag)[..]].parse().unwrap(), "{}", tag);
        assert_eq!(lay.place_bits, kv[&format!("{}_PLACE_BITS", tag)[..]].parse().unwrap(), "{}", tag);
        assert_eq!(lay.bits(), kv[&format!("{}_BITS", tag)[..]].parse().unwrap(), "{}", tag);
        assert_eq!(vector_room(&codes(), &s, rows_high), kv[&format!("{}_ROOM", tag)[..]].parse().unwrap(), "{}", tag);
        let want = ulist(kv[&format!("{}_INDEX", tag)[..]]);
        let got: Vec<u64> = (0..1u64 << lay.bits()).map(|j| lay.index(j)).collect();
        assert_eq!(got, want, "{} index", tag);
        let want = ulist(kv[&format!("{}_ENTRY_AT", tag)[..]]);
        let got: Vec<u64> = (0..1u64 << lay.bits()).map(|j| lay.entry_at(j)).collect();
        assert_eq!(got, want, "{} entry_at", tag);
        let want = eseq(kv[&format!("{}_ON_TABLE", tag)[..]]);
        let got: Vec<E> = (0..1u64 << lay.bits())
            .map(|j| lay.on_table(Tensor::eq(&z, 3, E::one())).at(j))
            .collect();
        assert_eq!(got, want, "{} on_table", tag);
    }

    // The committed table's numbers, pad places, faults and priced form.
    let a = index_shape();
    assert_eq!(a.rows(), kv["IDX_ROWS"].parse().unwrap());
    assert_eq!(a.pads(), kv["IDX_PADS"].parse().unwrap());
    assert_eq!(a.plain(), kv["IDX_PLAIN"].parse().unwrap());
    assert_eq!(a.cube_bits(), kv["IDX_CUBE_BITS"].parse().unwrap());
    let want = ulist(kv["IDX_PAD_PLACE"]);
    let mut got = Vec::new();
    for ans in 0..a.answers {
        for t in 0..E_DEGREE as u32 {
            got.push(a.pad_place(ans, t));
        }
    }
    assert_eq!(got, want);
    assert_eq!(fault_text(index_fault(&a)), kv["IDX_FAULT_A"]);
    let mut bad = a.clone();
    bad.code = Code { log_n: 0, ell: 0, r: 0 };
    assert_eq!(fault_text(index_fault(&bad)), kv["IDX_FAULT_CODE"]);
    bad = a.clone();
    bad.v = 41;
    assert_eq!(fault_text(index_fault(&bad)), kv["IDX_FAULT_ROWS"]);
    bad = a.clone();
    bad.code = Code { log_n: 4, ell: 4, r: 2 };
    assert_eq!(fault_text(index_fault(&bad)), kv["IDX_FAULT_PADS"]);
    bad = a.clone();
    bad.salt_bytes = 39;
    assert_eq!(fault_text(index_fault(&bad)), kv["IDX_FAULT_SALT"]);
    bad = a.clone();
    bad.answers = 0;
    assert_eq!(fault_text(index_fault(&bad)), kv["IDX_FAULT_ANSWERS"]);

    let p = priced_table(&a, TableTest::OneTime);
    assert_eq!(p.code.log_n, kv["PRICED_A_LOG_N"].parse().unwrap());
    assert_eq!(p.code.ell, kv["PRICED_A_ELL"].parse().unwrap());
    assert_eq!(p.code.r, kv["PRICED_A_R"].parse().unwrap());
    assert_eq!(p.v, kv["PRICED_A_V"].parse().unwrap());
    assert_eq!(p.answers, kv["PRICED_A_ANSWERS"].parse().unwrap());
    let d: Vec<u64> = kv["PRICED_A_DIST"].split(',').map(|x| x.parse().unwrap()).collect();
    assert_eq!(
        p.distances,
        TableDistances { radius: d[0], later_radius: d[1], m_once: d[2], m_later: d[3] }
    );
    assert_eq!(p.test as u32, kv["PRICED_A_TEST"].parse().unwrap());
    assert!(p.said);
    assert_eq!(p.said as u8, kv["PRICED_A_SAID"].parse().unwrap());

    // The table's name, digest bytes and tree.
    let root = digest(kv["DIGEST_ROOT"]);
    // KEY_CONFIG, TREE_A_RUN and TREE_A_PARAMS are printed word by word.
    let config = digest_words(kv["TREE_A_PARAMS"]);
    assert_eq!(index_name(&root, &a, &config), hex_bytes(kv["NAME_A"]));
    assert_eq!(digest_bytes(&root), hex_bytes(kv["DIGEST_ROOT"]));
    let tree = index_tree(&a, &config);
    assert_eq!(tree.log_n, kv["TREE_A_LOG_N"].parse().unwrap());
    assert_eq!(tree.log_n_zk, kv["TREE_A_LOG_N_ZK"].parse().unwrap());
    assert_eq!(tree.main_symbols, vec![kv["TREE_A_MAIN"].parse::<usize>().unwrap()]);
    assert_eq!(tree.mask_symbols, vec![kv["TREE_A_MASK"].parse::<usize>().unwrap()]);
    assert_eq!(tree.tree_number, kv["TREE_A_NUMBER"].parse().unwrap());
    assert_eq!(tree.salt_bytes, kv["TREE_A_SALT"].parse().unwrap());
    assert!(tree.stored);
    assert_eq!(tree.stored as u8, kv["TREE_A_STORED"].parse().unwrap());
    assert_eq!(tree.run, Digest::zero());
    assert_eq!(tree.run, digest_words(kv["TREE_A_RUN"]));
    assert_eq!(tree.parameters, config);
    assert_eq!(tree.parameters, digest_words(kv["TREE_A_PARAMS"]));

    // The record: its seeds, bytes and faults.
    let name = hex_bytes(kv["SEED_NAME"]);
    let mut rec = IndexRecord::default();
    rec.y = eseq(kv["FOLD_RECORD_Y"]);
    let seeds = record_seeds(&a, &name, &mut HashCalls::default());
    assert_eq!(seeds.len(), kv["SEED_COUNT"].parse::<usize>().unwrap());
    for (i, seed) in seeds.iter().enumerate() {
        let p = format!("SEED_{}", i);
        assert_eq!(seed.z, eseq(kv[&format!("{}_Z", p)[..]]), "{} z", p);
        assert_eq!(seed.beta, e(kv[&format!("{}_BETA", p)[..]]), "{} beta", p);
    }
    assert_eq!(record_bytes(&rec), hex_bytes(kv["RECORD_BYTES"]));
    assert_eq!(fault_text(record_fault(&a, &rec)), kv["RECORD_FAULT_A"]);
    let mut short = IndexRecord::default();
    short.y = vec![E::zero(); 7];
    assert_eq!(fault_text(record_fault(&a, &short)), kv["RECORD_FAULT_SHORT"]);

    // Public bytes and faults.
    let seed0 = seeds[0].clone();
    assert_eq!(public_bytes(&seed0), hex_bytes(kv["PUB_SEED_BYTES"]));
    assert_eq!(fault_text(seed0.public_fault()), kv["PUB_SEED_FAULT"]);
    let mut zero_seed = seed0.clone();
    zero_seed.beta = E::zero();
    assert_eq!(fault_text(zero_seed.public_fault()), kv["PUB_SEED_FAULT_ZERO"]);
    assert_eq!(public_bytes(&a), hex_bytes(kv["PUB_INDEX_BYTES"]));
    assert_eq!(fault_text(a.public_fault()), kv["PUB_INDEX_FAULT"]);
    assert_eq!(public_bytes(&rec), hex_bytes(kv["PUB_RECORD_BYTES"]));
    assert_eq!(fault_text(rec.public_fault()), kv["PUB_RECORD_FAULT"]);
    let index_name_value = IndexName { commitment: digest_bytes(&root), record: rec.clone() };
    assert_eq!(public_bytes(&index_name_value), hex_bytes(kv["PUB_NAME_BYTES"]));
    assert_eq!(fault_text(index_name_value.public_fault()), kv["PUB_NAME_FAULT"]);
    let empty_name = IndexName { commitment: Vec::new(), record: rec.clone() };
    assert_eq!(fault_text(empty_name.public_fault()), kv["PUB_NAME_FAULT_EMPTY"]);
    let short_name = IndexName { commitment: digest_bytes(&root), record: short.clone() };
    assert_eq!(fault_text(short_name.public_fault()), kv["PUB_NAME_FAULT_RECORD"]);

    // A key's bytes and faults.
    let key = IndexKey::new(a.clone(), &config, &root, rec.clone());
    assert_eq!(key.commitment(), hex_bytes(kv["KEY_COMMITMENT"]));
    assert_eq!(key.name(), hex_bytes(kv["KEY_NAME"]));
    assert_eq!(key.configuration(), config);
    assert_eq!(fault_text(key.fault()), kv["KEY_FAULT"]);
    assert_eq!(fault_text(index_key_fault(&key)), kv["KEY_FAULT_FN"]);
    assert_eq!(record_bytes(key.record()), hex_bytes(kv["KEY_RECORD_BYTES"]));
    let no_config = IndexKey::new(a.clone(), &Digest::zero(), &root, rec.clone());
    assert_eq!(fault_text(index_key_fault(&no_config)), kv["KEY_FAULT_NO_CONFIG"]);
    let bad_rec = IndexKey::new(a.clone(), &config, &root, short.clone());
    assert_eq!(fault_text(index_key_fault(&bad_rec)), kv["KEY_FAULT_BAD_RECORD"]);
    assert_eq!(fault_text(index_key_fault(&IndexKey::default())), kv["KEY_FAULT_DEFAULT"]);

    // FOLDEQ's shape, its public bytes and every fault.
    let s = fold_shape();
    assert_eq!(s.tail_first(), kv["FOLD_TAIL_FIRST"].parse().unwrap());
    assert_eq!(s.entries(), kv["FOLD_ENTRIES"].parse().unwrap());
    assert_eq!(public_bytes(&s), hex_bytes(kv["FOLD_PUBLIC_BYTES"]));
    assert_eq!(fault_text(s.public_fault()), kv["FOLD_PUBLIC_FAULT"]);
    assert_eq!(fault_text(foldeq_fault(&codes(), &s)), kv["FOLD_FAULT"]);
    let mut bad_s = s.clone();
    bad_s.u.main_rows = 0;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_NO_ROWS"]);
    bad_s = s.clone();
    bad_s.u.main_deg = 1;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_DEG"]);
    bad_s = s.clone();
    bad_s.u.answers = 0;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_NO_SAMPLE"]);
    bad_s = s.clone();
    bad_s.columns = 0;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_NO_COLUMNS"]);
    bad_s = s.clone();
    bad_s.u.code = 5;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_CODE"]);
    bad_s = s.clone();
    bad_s.u.main_rows = 1;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_ROOM"]);
    bad_s = s.clone();
    bad_s.index.salt_bytes = 39;
    assert_eq!(fault_text(foldeq_fault(&codes(), &bad_s)), kv["FOLD_FAULT_INDEX"]);

    // record_value and block_sums.
    let mut mf = Vec::new();
    let mut me = Vec::new();
    for i in 0..8 {
        mf.push(F(500 + i));
        me.push(E([F(700 + i), F(701 + i), F(702 + i)]));
    }
    for answer in 0..a.answers {
        assert_eq!(
            record_value(&a, &seed0, answer, &mf),
            e(kv[&format!("RECORD_VALUE_F_{}", answer)[..]])
        );
        assert_eq!(
            record_value(&a, &seed0, answer, &me),
            e(kv[&format!("RECORD_VALUE_E_{}", answer)[..]])
        );
    }
    let low = vec![E([F(31), F(32), F(33)]), E([F(32), F(33), F(34)])];
    assert_eq!(low, eseq(kv["BLOCK_LOW"]));
    let message: Vec<E> = (0..8).map(|i| E([F(900 + i), F(901 + i), F(902 + i)])).collect();
    let mut blocks = BlockSums { low, k_lo: 2, count: 2, sums: Vec::new() };
    block_sums(&message, &mut blocks);
    assert_eq!(blocks.sums, eseq(kv["BLOCK_SUMS"]));

    // The folded row's claims on G_u.
    let gamma = vec![E([F(21), F(22), F(23)]), E([F(22), F(23), F(24)])];
    let eq_gamma = foldeq_weights(&s, &gamma);
    assert_eq!(eq_gamma, eseq(kv["FOLD_EQ_GAMMA"]));
    let column = vec![F(101), F(102), F(103), F(104)];
    assert_eq!(foldeq_symbol(&eq_gamma, &column), e(kv["FOLD_SYMBOL"]));
    assert_eq!(rec.y, eseq(kv["FOLD_RECORD_Y"]));

    let mut st = Statement::new(codes());
    let oracle = st.sent(s.u.clone());
    assert_eq!(oracle, kv["FOLD_ORACLE"].parse().unwrap());
    for rh in [0u32, 1u32] {
        let mut sr = s.clone();
        sr.rows_high = rh != 0;
        let lay = vector_lay(&codes(), &sr.u, sr.rows_high);
        assert_eq!(lay.row_bits, kv[&format!("FOLD_RH{}_ROW_BITS", rh)[..]].parse().unwrap());
        assert_eq!(lay.place_bits, kv[&format!("FOLD_RH{}_PLACE_BITS", rh)[..]].parse().unwrap());
        assert_eq!(lay.bits(), kv[&format!("FOLD_RH{}_BITS", rh)[..]].parse().unwrap());
        let at = FoldedRow { oracle, lay };
        for i in 0..a.answers {
            let p = format!("FOLD_RH{}_REC{}", rh, i);
            let row = foldeq_record_row(&sr, &seeds[i as usize], &rec, i, &eq_gamma, &at);
            check_row(&kv, &p, oracle, &row, lay.bits());
        }
        for x in [0u64, 7, 15] {
            let p = format!("FOLD_RH{}_COL{}", rh, x);
            let y = e(kv[&format!("{}_Y", p)[..]]);
            let row = foldeq_column_row(&sr, x, &y, &at);
            check_row(&kv, &p, oracle, &row, lay.bits());
        }
    }

    // A predicate that the rows above cannot exercise without a reader: the standing enum
    // exists for the columns verifier. Its two names are compared here so that a rename is seen.
    assert_eq!(TableStanding::UnderTest as u32, 0);
    assert_eq!(TableStanding::AlreadyTested as u32, 1);
}
